-- An instance-local target links attack and damage; dawn advances its lifetime.
UPDATE dndshare.item_type SET fields=fields || jsonb_build_array($target_field${"key": "selected_target", "name": "Выбранная цель", "type": "object", "fields": [{"key": "title", "name": "Название блока", "type": "text", "default": "Выбранная цель", "hint": "Заголовок панели под оружием. Имя противника игрок вводит на листе."}, {"key": "condition", "name": "Когда объявляют цель", "type": "text", "hint": "Условие проверяет игрок, например при дальней атаке этим оружием."}, {"key": "duration_dawns", "name": "Длительность, рассветов", "type": "int", "default": 7, "min": 1, "max": 100, "hint": "Срок уменьшается через пункт «Рассвет», независимо от отдыха и реального времени."}, {"key": "cooldown_dawns", "name": "После гибели ждать рассветов", "type": "int", "default": 1, "min": 0, "max": 100, "hint": "Ноль — новую цель можно выбрать сразу. Пока цель жива, заменить её нельзя."}, {"key": "ranged_only", "name": "Только дальние атаки", "type": "bool", "default": true, "hint": "Ограничивает бонусы по цели дальними атаками этого оружия."}, {"key": "attack_advantage", "name": "Преимущество против цели", "type": "bool", "hint": "Применяется при включённой галочке атаки по выбранной цели. Помеха от других эффектов учитывается."}, {"key": "other_weapons_disadvantage", "name": "Помеха другому оружию", "type": "bool", "hint": "Пока цель жива. Продолжает действовать, если источник убрали в сумку; безоружные удары и заклинания не затрагиваются."}, {"key": "ignore_partial_cover", "name": "Игнорирует неполное укрытие", "type": "bool", "hint": "Памятка игроку. Полное укрытие продолжает действовать; карта и КД цели не рассчитываются."}, {"key": "ignore_long_range", "name": "Без помехи от дальней дистанции", "type": "bool", "hint": "Памятка игроку: приложение не определяет расстояние до цели автоматически."}, {"key": "damage", "name": "Дополнительный урон по цели", "type": "object", "fields": [{"key": "dice", "name": "Кость", "type": "select", "default": "d6", "options": [{"value": "d4", "label": "к4"}, {"value": "d6", "label": "к6"}, {"value": "d8", "label": "к8"}, {"value": "d10", "label": "к10"}, {"value": "d12", "label": "к12"}, {"value": "d20", "label": "к20"}, {"value": "d100", "label": "к100"}]}, {"key": "dice_count", "name": "Количество костей", "type": "int", "default": 1, "min": 1, "max": 100}, {"key": "damage_type", "name": "Тип урона", "type": "suggest", "suggest_id": 12}]}]}$target_field$::jsonb)
WHERE id=19 AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(fields) f WHERE f->>'key'='selected_target');

UPDATE dndshare.item SET data=jsonb_set(jsonb_set(data,'{selected_target}',$oath_target${"title": "Заклятый враг", "condition": "Объявите цель при дальней атаке этим луком, произнеся командную фразу. Одновременно — один противник.", "duration_dawns": 7, "cooldown_dawns": 1, "ranged_only": true, "attack_advantage": true, "other_weapons_disadvantage": true, "ignore_partial_cover": true, "ignore_long_range": true, "damage": {"dice": "d6", "dice_count": 3, "damage_type": 1}}$oath_target$::jsonb),'{weapon_damage}',
 COALESCE((SELECT jsonb_agg(r) FROM jsonb_array_elements(COALESCE(data->'weapon_damage','[]'::jsonb)) r WHERE r->>'key' IS DISTINCT FROM 'sworn_enemy'),'[]'::jsonb))
WHERE id=202 AND name='Лук клятвы' AND type_id=19 AND user_id IS NULL AND NOT data ? 'selected_target';
